    v: ["a chave=la llave", "o bolso=el bolsillo", "a carteira=la cartera", "procurar=buscar", "encontrar=encontrar", "perder=perder", "entregar=entregar", "devolver=devolver", "perdoar=perdonar", "zangar-se=enfadarse", "ter razão=tener razón", "em lado nenhum=en ningún sitio"],
    s: ["Onde puseste as chaves do carro?|¿Dónde has puesto las llaves del coche?", "Não as encontro em lado nenhum.|No las encuentro en ningún sitio.", "Tenho-as aqui no bolso.|Las tengo aquí en el bolsillo.", "Vou buscar as crianças.|Voy a recoger a los niños.", "Tens razão, desculpa.|Tienes razón, perdona."],
